// Sogang University, Sinchon campus (서강대학교 신촌캠퍼스, 서울 마포구 노고산). Data is generated by scripts/campuses/sogang/build-package.mjs
// from the pilot (pilot/sogang-sinchon, round 3): the destructible buildings of active-models.json (본관·로욜라도서관 1·2·3관·리치과학관·
// 엠마오관 스탠드동 detailed, the rest generic), the pilot's destructible:false models as protected (성이냐시오관 = the university chapel,
// 예수회공동체; shield, never damaged), a baked ground with the pilot's ground look (src/campuses/sogang/ground-look.js), the planting of
// site/planting.mjs (same trees as the preview), the pilot's landscape/ models and the non-destructible context (신촌·마포, 노고산 woods)
// fading into the haze. Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, SG_PLACEMENTS, SG_BUILDING_BASE, SG_HEIGHT_GRIDS, SG_HEIGHT_RANGE_M, SG_ENV_IDS, SG_ENV_MANIFEST_IDS, SG_LOOK, SG_DISPLAY, SG_PROVENANCE } from './data.js';
import { SG_FOOTPRINTS } from './footprints.js';
import { SG_PROTECTED } from './protected.js';
import { createSogangGroundLook } from './ground-look.js';

const MODEL_IDS = Object.freeze(SG_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/sogang/${file}`, import.meta.url).href;
const HAZE = SG_DISPLAY.haze, FADE = SG_DISPLAY.fade;

export const SOGANG = Object.freeze({
  id: 'sogang',
  meta: Object.freeze({ school: '서강대학교', campus: '신촌캠퍼스', short: '서강대', modelNoun: '서강대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: SG_PLACEMENTS,
  approvedCount: SG_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['main', 'centreHall', 'emmaus', 'library1', 'library2', 'libraryLaw'].filter(id => MODEL_IDS.includes(id))),
  startBuildingId: 'centreHall',
  // Start: from over the 대운동장 (south-south-west) across the field to 엠마오관 and its stepped stand, 본관 on the left, the
  // 로욜라도서관 1·2·3관 terraces on the slope behind to the right and 노고산 above. Box = E -100..130 m, N -40..105 m
  // (world units: metres x 0.5, z = -N); azimuth -.35 = camera to the south-south-west of the box.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-50, 5, -52.5]), max: Object.freeze([65, 22, 20]), azimuth: -.35 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: SG_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: SG_HEIGHT_GRIDS, buildingBase: SG_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30 + floor-link / photo level evidence, pilot/sogang-sinchon); not a survey' }),
  environment: Object.freeze({ provenance: SG_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the place models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: SG_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSogangGroundLook(SG_LOOK),
      // context.json display fade (preview.js FADE): campus clear to r0, the backdrop melts into the haze by r1
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, ...(FADE.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/sogang-sinchon preview ground + planting + landscape + context, baked' }),
  }),
  // Protected (pilot destructible:false: 성이냐시오관 = university chapel, 예수회공동체): never destructible; weapons meet the protective
  // shield (src/protected-buildings.js); own manifest, models packed with the campus cache (shared textures).
  protected: Object.freeze({
    manifestURL: asset('protected/manifest.json'),
    models: SG_PROTECTED,
  }),
  // Hazard tape around every destructible building only (src/engine/hazard-tape.js): none on the protected models or the context.
  hazardTape: Object.freeze({ footprints: SG_FOOTPRINTS }),
  scene: Object.freeze({
    // preview.js: fog 1400..3200 m, hemisphere (#fff, #7d8a78, 1.35), sun #fff4e2 3.1 from (-260, 320, 220) to (0, 20, 40 EN) -> halved
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 700, far: 1600 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-130, 150, 130]), shadowSpan: 240 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: SG_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default SOGANG;
